namespace sv_22b124e15f8b4e9994c0d04588218933.Components;

public enum ScreenSize
{
    Mobile,
    Tablet,
    Desktop
}

@implements IAsyncDisposable
@inject IJSRuntime JS

<CascadingValue Value="currentSize">
    @ChildContent
</CascadingValue>

@code {
    [Parameter]
    public RenderFragment? ChildContent { get; set; }

    private ScreenSize currentSize = ScreenSize.Desktop;
    private IJSObjectReference? module;
    private DotNetObjectReference<ScreenSizeProvider>? dotNetRef;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            dotNetRef = DotNetObjectReference.Create(this);
            module = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./_content/sv-22b124e15f8b4e9994c0d04588218933/screenSize.js");
            var width = await module.InvokeAsync<int>("initialize", dotNetRef);
            UpdateSize(width);
        }
    }

    [JSInvokable]
    public void OnResize(int width)
    {
        UpdateSize(width);
    }

    private void UpdateSize(int width)
    {
        var newSize = width switch
        {
            < 768 => ScreenSize.Mobile,
            < 1024 => ScreenSize.Tablet,
            _ => ScreenSize.Desktop
        };

        if (newSize != currentSize)
        {
            currentSize = newSize;
            StateHasChanged();
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (module is not null)
        {
            await module.InvokeVoidAsync("dispose");
            await module.DisposeAsync();
        }
        dotNetRef?.Dispose();
    }
}

let dotNetRef = null;
let handler = null;

export function initialize(ref) {
    dotNetRef = ref;
    handler = () => dotNetRef.invokeMethodAsync("OnResize", window.innerWidth);
    window.addEventListener("resize", handler);
    return window.innerWidth;
}

export function dispose() {
    if (handler) {
        window.removeEventListener("resize", handler);
        handler = null;
    }
    dotNetRef = null;
}

